import re
import requests

def task_func(input):
    match = re.search(r'https?://[^\s<>"\']+', input)
    if not match:
        raise ValueError("No HTTP/HTTPS URL found in input")

    endpoint = match.group(0).rstrip('.,;:!?)]}\'"')

    try:
        response = requests.get(endpoint, timeout=10)
        response.raise_for_status()
        data = response.json()
    except requests.RequestException as e:
        raise RuntimeError(f"Failed to fetch endpoint: {e}") from e
    except ValueError as e:
        raise ValueError(f"Response is not valid JSON: {e}") from e

    if not isinstance(data, dict):
        raise ValueError("JSON response must be an object (dict)")

    return data
